},\"payload\":{\"type\":\"object\"},\"seq\":{\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"op_id\",\"op_type\",\"op_version\",\"entity_type\",\"entity_id\",\"device_id\",\"hlc\",\"payload\",\"seq\",\"caused_by_op_id\"],\"type\":\"object\"},\"maxItems\":1000,\"type\":\"array\"},\"server_time\":{\"\$ref\":\"common.schema.json#/\$defs/instant_ms\",\"description\":\"As in PushResponse.\"}},\"required\":[\"ops\",\"next_since\",\"has_more\",\"high_water_seq\",\"server_time\",\"log_epoch\",\"durable_seq\"],\"title\":\"PullResponseLenient\",\"type\":\"object\"},\"PushRequest\":{\"additionalProperties\":false,\"description\":\"Body of POST /sync/push.\",\"properties\":{\"ops\":{\"description\":\"Ops minted by ONE device (all device_id equal), in strictly ascending hlc. The server processes them in array order.\",\"items\":{\"allOf\":[{\"\$ref\":\"op.schema.json\"},{\"properties\":{\"caused_by_op_id\":false,\"seq\":false}}]},\"maxItems\":500,\"minItems\":1,\"type\":\"array\"}},\"required\":[\"ops\"],\"title\":\"PushRequest\",\"type\":\"object\"},\"PushRequestLenient\":{\"description\":\"What the server validates a push body against; the only whole-body check it may fail a push request on (HTTP 400). Everything stricter (op.schema.json, the envelope rules, the per-op checks of SYNC.md 5.3) is checked per op and reported as a 'rejected' result with unsupported_op, schema_invalid, ..., so one bad op never blocks the rest of the outbox. Duplicate keys (C-2, SYNC.md 5.2 'Parsing the body'): the server parses the body with a syntax-only, duplicate-tolerant parse. The body ALSO fails this shape (HTTP 400) if the top-level object repeats a key, if an element's op_id member is repeated, or if two elements have the same op_id with different contents. A duplicate key anywhere inside ops[i] is NOT a 400: that op is rejected with schema_invalid, decided before op_too_large. JSON Schema cannot express duplicate keys; these rules are normative text.\",\"properties\":{\"ops\":{\"items\":{\"properties\":{\"op_id\":{\"\$ref\":\"common.schema.json#/\$defs/uuid\"}},\"required\":[\"op_id\"],\"type\":\"object\"},\"maxItems\":500,\"minItems\":1,\"type\":\"array\"}},\"required\":[\"ops\"],\"title\":\"PushRequestLenient\",\"type\":\"object\"},\"PushResponse\":{\"additionalProperties\":false,\"description\":\"Body of a successful POST /sync/push response.\",\"properties\":{\"durable_seq\":{\"description\":\"Highest seq s such that every change row with seq <= s is in a verified backup that any restore will start from (SYNC.md 6.2). <= high_water_seq; never decreases within one log_epoch. A device keeps each acked pending_op row until acked_seq <= durable_seq.\",\"minimum\":0,\"type\":\"integer\"},\"high_water_seq\":{\"description\":\"Highest change.seq committed when the response was built; >= every seq in results. A client whose pull_seq is greater starts a log reset (SYNC.md 6.2); otherwise informational (pending pull count).\",\"minimum\":0,\"type\":\"integer\"},\"log_epoch\":{\"\$ref\":\"common.schema.json#/\$defs/uuid\",\"description\":\"Identity of the server's log (SYNC.md 6.2). Changes only when the log is replaced (a restore from backup): seq values of different epochs are unrelated. A client that sees a value different from the one it stored starts a log reset.\"},\"results\":{\"description\":\"Exactly one result per pushed op, in request order.\",\"items\":{\"\$ref\":\"#/\$defs/PushResult\"},\"type\":\"array\"},\"server_time\":{\"\$ref\":\"common.schema.json#/\$defs/instant_ms\",\"description\":\"Server wall clock when the response was built; clients compare it with their own clock to warn about skew and to block minting when it exceeds 24 h (SYNC.md 3.4).\"}},\"required\":[\"results\",\"high_water_seq\",\"server_time\",\"log_epoch\",\"durable_seq\"],\"title\":\"PushResponse\",\"type\":\"object\"},\"PushResult\":{\"additionalProperties\":false,\"allOf\":[{\"else\":{\"properties\":{\"error\":false},\"required\":[\"seq\"]},\"if\":{\"properties\":{\"status\":{\"const\":\"rejected\"}},\"required\":[\"status\"]},\"then\":{\"properties\":{\"seq\":false},\"required\":[\"error\"]}}],\"description\":\"Outcome of one pushed op.\",\"properties\":{\"error\":{\"additionalProperties\":false,\"description\":\"Present iff status = rejected.\",\"properties\":{\"code\":{\"description\":\"Machine-readable reason (SYNC.md section 5.3). Open set: clients treat an unknown code as a generic permanent rejection.\",\"examples\":[\"op_too_large\",\"unsupported_op\",\"schema_invalid\",\"device_mismatch\",\"server_only\",\"unknown_reference\",\"clock_ahead\",\"clock_behind\",\"invalid_value\",\"invalid_target\",\"immutable\"],\"pattern\":\"^[a-z][a-z0-9_]*\$\",\"type\":\"string\"},\"message\":{\"description\":\"English diagnostic for logs and the sync-status screen; not for parsing.\",\"type\":\"string\"}},\"required\":[\"code\",\"message\"],\"type\":\"object\"},\"op_id\":{\"\$ref\":\"common.schema.json#/\$defs/uuid\",\"description\":\"The op this result is for.\"},\"seq\":{\"description\":\"change.seq of the op. Present iff status is accepted or duplicate.\",\"minimum\":1,\"type\":\"integer\"},\"status\":{\"description\":\"accepted: applied and logged now. duplicate: this op_id was already in the log; nothing was done. rejected: permanently refused; nothing was done.\",\"enum\":[\"accepted\",\"duplicate\",\"rejected\"]}},\"required\":[\"op_id\",\"status\"],\"title\":\"PushResult\",\"type\":\"object\"}},\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Entry point for the sync HTTP bodies. A document is exactly one of the three shapes; reference a specific one as batch.schema.json#/\$defs/PushRequest, #/\$defs/PushResponse or #/\$defs/PullResponse. SYNC.md sections 5 and 6. Two lenient shapes say what a RECEIVER validates the whole body against: the server validates a push body against #/\$defs/PushRequestLenient only (a mismatch is HTTP 400) and checks each op on its own, so a single op can be answered with unsupported_op or schema_invalid while the rest of the batch is processed; a client validates a pull body against #/\$defs/PullResponseLenient and checks each op against op.schema.json only when it knows the op_type and op_version, so an old client applies the ops before the first unknown one and stops there (SYNC.md 6, 'upgrade required'). PushRequest and PullResponse are what a correct SENDER produces.\",\"oneOf\":[{\"\$ref\":\"#/\$defs/PushRequest\"},{\"\$ref\":\"#/\$defs/PushResponse\"},{\"\$ref\":\"#/\$defs/PullResponse\"}],\"title\":\"Sync batch\"}",
