        "ops/deck.created.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"allOf\":[{\"else\":{\"properties\":{\"query\":false}},\"if\":{\"properties\":{\"type\":{\"const\":\"smart\"}},\"required\":[\"type\"]},\"then\":{\"required\":[\"query\"]}},{\"else\":{\"properties\":{\"media_id\":false}},\"if\":{\"properties\":{\"type\":{\"const\":\"media\"}},\"required\":[\"type\"]},\"then\":{\"required\":[\"media_id\"]}},{\"else\":{\"properties\":{\"list_key\":false}},\"if\":{\"properties\":{\"type\":{\"const\":\"list\"}},\"required\":[\"type\"]},\"then\":{\"required\":[\"list_key\"]}}],\"description\":\"Creates a deck. Clients may create type user and smart only; media and list decks are created by the server. OPS.md#deckcreated\",\"properties\":{\"enabled\":{\"default\":true,\"description\":\"false = supplies no new cards. Default true.\",\"type\":\"boolean\"},\"id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"Id of the new deck (for a media deck: equal to media_id). Equals the envelope's entity_id.\"},\"language\":{\"const\":\"ja\",\"description\":\"Default 'ja'.\"},\"list_key\":{\"description\":\"Required iff type = list. Slug, e.g. jlpt-n3.\",\"pattern\":\"^[a-z0-9][a-z0-9-]*\$\",\"type\":\"string\"},\"media_id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"Required iff type = media; equals id.\"},\"name\":{\"description\":\"Display name; not unique.\",\"maxLength\":200,\"minLength\":1,\"type\":\"string\"},\"new_cards_per_day\":{\"anyOf\":[{\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Per-deck daily new-card limit; null = only the global limit applies.\"},\"priority\":{\"default\":0,\"description\":\"New cards are drawn from enabled decks in ascending (priority, id). Default 0.\",\"maximum\":2147483647,\"minimum\":-2147483648,\"type\":\"integer\"},\"query\":{\"description\":\"Card search-language string. Required iff type = smart.\",\"type\":\"string\"},\"reviews_per_day\":{\"anyOf\":[{\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Per-deck daily review limit; null = only the global limit applies.\"},\"settings\":{\"default\":{},\"description\":\"Open object; each top-level key is its own register 'settings.<key>'. Known keys: order, add_kanji, card_kinds. Keys whose value is null, '', [] or {} are dropped at creation.\",\"propertyNames\":{\"\$ref\":\"../common.schema.json#/\$defs/key\"},\"type\":\"object\"},\"type\":{\"description\":\"Immutable. media and list: server-emitted only.\",\"enum\":[\"user\",\"media\",\"list\",\"smart\"]}},\"required\":[\"id\",\"name\",\"type\"],\"title\":\"deck.created\",\"type\":\"object\"}",
