e\":\"number\"},{\"description\":\"w[6]\",\"maximum\":4,\"minimum\":0.001,\"type\":\"number\"},{\"description\":\"w[7]\",\"maximum\":0.75,\"minimum\":0.001,\"type\":\"number\"},{\"description\":\"w[8]\",\"maximum\":4.5,\"minimum\":0,\"type\":\"number\"},{\"description\":\"w[9]\",\"maximum\":0.8,\"minimum\":0,\"type\":\"number\"},{\"description\":\"w[10]\",\"maximum\":3.5,\"minimum\":0.001,\"type\":\"number\"},{\"description\":\"w[11]\",\"maximum\":5,\"minimum\":0.001,\"type\":\"number\"},{\"description\":\"w[12]\",\"maximum\":0.25,\"minimum\":0.001,\"type\":\"number\"},{\"description\":\"w[13]\",\"maximum\":0.9,\"minimum\":0.001,\"type\":\"number\"},{\"description\":\"w[14]\",\"maximum\":4,\"minimum\":0,\"type\":\"number\"},{\"description\":\"w[15]\",\"maximum\":1,\"minimum\":0,\"type\":\"number\"},{\"description\":\"w[16]\",\"maximum\":6,\"minimum\":1,\"type\":\"number\"},{\"description\":\"w[17]\",\"maximum\":2,\"minimum\":0,\"type\":\"number\"},{\"description\":\"w[18]\",\"maximum\":2,\"minimum\":0,\"type\":\"number\"},{\"description\":\"w[19]\",\"maximum\":0.8,\"minimum\":0,\"type\":\"number\"},{\"description\":\"w[20]\",\"maximum\":0.8,\"minimum\":0.1,\"type\":\"number\"}],\"type\":\"array\"},\"weights_version\":{\"description\":\"New version, = previous + 1.\",\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"id\",\"weights_version\",\"fsrs_version\",\"weights\",\"optimized_at\"],\"title\":\"fsrs_params.published\",\"type\":\"object\"}",
        "ops/fsrs_params.updated.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Sets a subset of a preset's registers. A winning write to any register except 'name' forces a replay of every card on the preset. OPS.md#fsrs_paramsupdated\",\"properties\":{\"id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"Id of the preset. Equals the envelope's entity_id.\"},\"set\":{\"additionalProperties\":false,\"description\":\"Registers to write. At least one.\",\"minProperties\":1,\"properties\":{\"desired_retention\":{\"description\":\"Register 'desired_retention'. Column default 0.9.\",\"exclusiveMaximum\":1,\"exclusiveMinimum\":0,\"type\":\"number\"},\"easy_days\":{\"description\":\"Register 'easy_days': load multiplier per ISO weekday, Monday first. Column default [1,1,1,1,1,1,1].\",\"items\":{\"maximum\":1,\"minimum\":0,\"type\":\"number\"},\"maxItems\":7,\"minItems\":7,\"type\":\"array\"},\"fuzz\":{\"description\":\"Register 'fuzz'. Column default true.\",\"type\":\"boolean\"},\"learning_steps_s\":{\"description\":\"Register 'learning_steps_s': steps in seconds, in order; [] = none.\",\"items\":{\"minimum\":1,\"type\":\"integer\"},\"maxItems\":20,\"type\":\"array\"},\"maximum_interval_days\":{\"description\":\"Register 'maximum_interval_days'. Column default 36500.\",\"maximum\":2147483647,\"minimum\":1,\"type\":\"integer\"},\"name\":{\"description\":\"Register 'name'.\",\"maxLength\":200,\"minLength\":1,\"type\":\"string\"},\"relearning_steps_s\":{\"description\":\"Register 'relearning_steps_s': steps in seconds, in order; [] = none.\",\"items\":{\"minimum\":1,\"type\":\"integer\"},\"maxItems\":20,\"type\":\"array\"}},\"type\":\"object\"}},\"required\":[\"id\",\"set\"],\"title\":\"fsrs_params.updated\",\"type\":\"object\"}",
