 share, reader, deck, jpdb_import, api, auto_kanji. Open set. Immutable. Default 'manual'.\",\"pattern\":\"^[a-z][a-z0-9_]*\$\",\"type\":\"string\"},\"source_media_id\":{\"anyOf\":[{\"\$ref\":\"../common.schema.json#/\$defs/uuid\"},{\"type\":\"null\"}],\"default\":null,\"description\":\"Soft reference to media.id, or null.\"},\"source_sentence\":{\"default\":\"\",\"description\":\"Sentence the note was mined from, by value; '' if none. Register 'source_sentence' covers this and the two columns below.\",\"type\":\"string\"},\"source_sentence_id\":{\"anyOf\":[{\"\$ref\":\"../common.schema.json#/\$defs/uuid\"},{\"type\":\"null\"}],\"default\":null,\"description\":\"Soft reference to sentence.id, or null.\"},\"tags\":{\"\$ref\":\"../common.schema.json#/\$defs/tags\",\"default\":[]}},\"required\":[\"id\",\"note_type_id\"],\"title\":\"note.created\",\"type\":\"object\"}",
