\":\"note_type.created\",\"type\":\"object\"}",
        "ops/note_type.deleted.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Tombstones a user-defined note type. Rejected for built-ins. OPS.md#note_typedeleted\",\"properties\":{\"id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"Id of the note type. Equals the envelope's entity_id.\"}},\"required\":[\"id\"],\"title\":\"note_type.deleted\",\"type\":\"object\"}",
        "ops/note_type.updated.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Sets a subset of a note type's registers, all at the op's hlc. OPS.md#note_typeupdated\",\"properties\":{\"id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"Id of the note type. Equals the envelope's entity_id.\"},\"set\":{\"additionalProperties\":false,\"description\":\"Registers to write. At least one.\",\"minProperties\":1,\"properties\":{\"css\":{\"description\":\"Register 'css'.\",\"type\":\"string\"},\"fields\":{\"description\":\"Ordered field definitions; the whole array is ONE register ('fields'). Keys must be unique within the array (server rejects duplicates with invalid_value). Keys are never renamed. For a vocab note type the keys MUST include expression, reading and meaning (invalid_value otherwise; OPS.md, C-2).\",\"items\":{\"description\":\"One field. Unknown keys are preserved.\",\"properties\":{\"key\":{\"\$ref\":\"../common.schema.json#/\$defs/key\",\"description\":\"Field key used in note.fields and {{placeholders}}.\"},\"kind\":{\"description\":\"What the field holds.\",\"enum\":[\"text\",\"audio\",\"image\"]},\"label\":{\"description\":\"Display label.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"key\",\"label\",\"kind\"],\"type\":\"object\"},\"maxItems\":100,\"minItems\":1,\"type\":\"array\"},\"name\":{\"description\":\"Register 'name'.\",\"maxLength\":200,\"minLength\":1,\"type\":\"string\"},\"templates\":{\"additionalProperties\":{\"anyOf\":[{\"\$ref\":\"../common.schema.json#/\$defs/template\"},{\"type\":\"null\"}]},\"description\":\"One register 'templates.<kind>' per key present. null removes the kind from the object (the register keeps its clock).\",\"minProperties\":1,\"propertyNames\":{\"\$ref\":\"../common.schema.json#/\$defs/key\"},\"type\":\"object\"}},\"type\":\"object\"}},\"required\":[\"id\",\"set\"],\"title\":\"note_type.updated\",\"type\":\"object\"}",
        "ops/parse_override.deleted.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Tombstones a parse override (permanent). Server only: devices skip it. OPS.md#parse_overridedeleted\",\"properties\":{\"id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"Id of the parse override. Equals the envelope's entity_id.\"}},\"required\":[\"id\"],\"title\":\"parse_override.deleted\",\"type\":\"object\"}",
        "ops/parse_override.put.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Creates or replaces a tokenisation correction (whole row, last-writer-wins on hlc). Server only: devices skip it. OPS.md#parse_overrideput\",\"if\":{\"properties\":{\"sentence_id\":{\"type\":\"string\"}},\"required\":[\"sentence_id\"]},\"properties\":{\"id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"Id of the parse override. Equals the envelope's entity_id.\"},\"match_text\":{\"description\":\"Exact surface substring this override re-tokenises.\",\"minLength\":1,\"type\":\"string\"},\"media_id\":{\"anyOf\":[{\"\$ref\":\"../common.schema.json#/\$defs/uuid\"},{\"type\":\"null\"}],\"description\":\"Scope: null = all media. Soft reference. Default null.\"},\"note\":{\"default\":\"\",\"description\":\"Free-text remark. Default ''.\",\"type\":\"string\"},\"sentence_id\":{\"anyOf\":[{\"\$ref\":\"../common.schema.json#/\$defs/uuid\"},{\"type\":\"null\"}],\"description\":\"Narrowest scope: one sentence; requires media_id. Soft reference. Default null.\"},\"tokens\":{\"description\":\"Replacement tokens; surfaces must concatenate to match_text (server rejects otherwise).\",\"items\":{\"description\":\"Unknown keys are preserved.\",\"properties\":{\"lemma\":{\"description\":\"Dictionary form.\",\"type\":\"string\"},\"seq\":{\"anyOf\":[{\"\$ref\":\"../common.schema.json#/\$defs/entry_seq\"},{\"type\":\"null\"}],\"description\":\"Entry; null = force 'no entry'.\"},\"surface\":{\"description\":\"Token surface.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"surface\"],\"type\":\"object\"},\"minItems\":1,\"type\":\"array\"}},\"required\":[\"id\",\"match_text\",\"tokens\"],\"then\":{\"properties\":{\"media_id\":{\"type\":\"string\"}},\"required\":[\"media_id\"]},\"title\":\"parse_override.put\",\"type\":\"object\"}",
        "ops/review.logged.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"allOf\":[{\"else\":{\"properties\":{\"manual_action\":{\"type\":\"null\"},\"manual_due_at\":{\"type\":\"null\"},\"rating\":{\"type\":\"integer\"}}},\"if\":{\"properties\":{\"review_type\":{\"const\":\"manual\"}},\"required\":[\"review_type\"]},\"then\":{\"properties\":{\"button\":{\"type\":\"null\"},\"manual_action\":{\"enum\":[\"set_due\",\"reset\"]},\"rating\":{\"type\":\"null\"}},\"required\":[\"manual_action\"]}},{\"else\":{\"properties\":{\"manual_due_at\":{\"type\":\"null\"}}},\"if\":{\"properties\":{\"manual_action\":{\"const\":\"set_due\"}},\"required\":[\"manual_action\"]},\"then\":{\"properties\":{\"manual_due_at\":{\"type\":\"integer\"}},\"required\":[\"manual_due_at\"]}},{\"if\":{\"properties\":{\"button\":{\"enum\":[\"again\",\"nothing\",\"something\"]}},\"required\":[\"button\"]},\"then\":{\"properties\":{\"rating\":{\"const\":1}}}},{\"if\":{\"properties\":{\"button\":{\"enum\":[\"hard\"]}},\"required\":[\"button\"]},\"then\":{\"properties\":{\"rating\":{\"const\":2}}}},{\"if\":{\"properties\":{\"button\":{\"enum\":[\"good\",\"okay\"]}},\"required\":[\"button\"]},\"then\":{\"properties\":{\"rating\":{\"const\":3}}}},{\"if\":{\"properties\":{\"button\":{\"enum\":[\"easy\"]}},\"required\":[\"button\"]},\"then\":{\"properties\":{\"rating\":{\"const\":4}}}},{\"if\":{\"properties\":{\"replay_hlc\":{\"type\":\"string\"}},\"required\":[\"replay_hlc\"]},\"then\":{\"properties\":{\"import_source\":{\"const\":\"jpdb\"}},\"required\":[\"import_source\"]}}],\"description\":\"Appends one row to review_log. Never conflicts. OPS.md#reviewlogged\",\"properties\":{\"button\":{\"anyOf\":[{\"enum\":[\"again\",\"hard\",\"good\",\"easy\",\"nothing\",\"something\",\"okay\"]},{\"type\":\"null\"}],\"description\":\"Button pressed; must agree with rating (again/nothing/something=1, hard=2, good/okay=3, easy=4). null = unknown, and always null for manual. Default null.\"},\"card_id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"Card as it was on the reviewing device; must exist on the server (may be tombstoned or merged). Never rewritten.\"},\"duration_ms\":{\"anyOf\":[{\"maximum\":600000,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Time from card shown to answer, capped at 600000; null = unknown. Default null.\"},\"id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"review_log.id (UUIDv7 from the reviewing client). Equals entity_id. Distinct from op_id.\"},\"import_source\":{\"anyOf\":[{\"const\":\"jpdb\"},{\"type\":\"null\"}],\"description\":\"Server-emitted import ops only: 'jpdb'. Clients MUST omit it or send null.\"},\"manual_action\":{\"anyOf\":[{\"enum\":[\"set_due\",\"reset\"]},{\"type\":\"null\"}],\"description\":\"Required (non-null) iff review_type = manual. set_due: keep memory state, due := manual_due_at. reset: card returns to state new.\"},\"manual_due_at\":{\"anyOf\":[{\"\$ref\":\"../common.schema.json#/\$defs/instant_ms\"},{\"type\":\"null\"}],\"description\":\"Non-null iff manual_action = set_due.\"},\"rating\":{\"anyOf\":[{\"maximum\":4,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"FSRS rating 1 Again, 2 Hard, 3 Good, 4 Easy. null iff review_type = manual.\"},\"replay_hlc\":{\"anyOf\":[{\"\$ref\":\"../common.schema.json#/\$defs/hlc\"},{\"type\":\"null\"}],\"description\":\"Server-emitted import ops only: the value stored in review_log.hlc (replay position), synthesised as <historical ms>-<running counter>-<server device id>. When absent/null, review_log.hlc = the op's hlc. Requires import_source.\"},\"review_type\":{\"description\":\"scheduled, learning, manual feed the schedule (replay set); drill, cram are logged only.\",\"enum\":[\"scheduled\",\"learning\",\"drill\",\"cram\",\"manual\"]},\"reviewed_at\":{\"\$ref\":\"../common.schema.json#/\$defs/instant_ms\",\"description\":\"Wall-clock instant of the answer on the reviewing device.\"},\"sentence_id\":{\"anyOf\":[{\"\$ref\":\"../common.schema.json#/\$defs/uuid\"},{\"type\":\"null\"}],\"description\":\"Sentence shown for rotating-example cards (soft reference). Default null.\"},\"utc_offset_min\":{\"anyOf\":[{\"maximum\":1080,\"minimum\":-1080,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Device UTC offset in minutes at review time (540 = JST); null = unknown. Native clients MUST send a number.\"}},\"required\":[\"id\",\"card_id\",\"reviewed_at\",\"utc_offset_min\",\"review_type\",\"rating\"],\"title\":\"review.logged\",\"type\":\"object\"}",
        "ops/review.undone.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Marks a review undone. The EARLIEST undo (smallest hlc) wins. An undo cannot be undone. OPS.md#reviewundone\",\"properties\":{\"review_id\":{\"\$ref\":\"../common.schema.json#/\$defs/uuid\",\"description\":\"review_log.id to undo. Equals entity_id. Must exist on the server.\"}},\"required\":[\"review_id\"],\"title\":\"review.undone\",\"type\":\"object\"}",
        "ops/settings.set.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Writes one settings key (one register per key). OPS.md#settingsset\",\"properties\":{\"key\":{\"description\":\"Dotted lowercase key, e.g. scheduler.new_per_day. Equals entity_id.\",\"maxLength\":200,\"pattern\":\"^[a-z][a-z0-9_]*(\\\\.[a-z][a-z0-9_]*)*\$\",\"type\":\"string\"},\"value\":{\"description\":\"Any JSON value. null = reset to default (the row stays so the reset beats older sets).\"}},\"required\":[\"key\",\"value\"],\"title\":\"settings.set\",\"type\":\"object\"}",
        "ops/word.status_cleared.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Clears the override (same register as word.status_set, value null), so the effective status falls back to the automatic one. OPS.md#wordstatus_cleared\",\"properties\":{\"entry_seq\":{\"\$ref\":\"../common.schema.json#/\$defs/entry_seq\",\"description\":\"Entry. entity_id is its decimal text.\"}},\"required\":[\"entry_seq\"],\"title\":\"word.status_cleared\",\"type\":\"object\"}",
        "ops/word.status_set.schema.json" to
            "{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"additionalProperties\":false,\"description\":\"Writes the explicit status override of a dictionary entry (one register: override_status + override_origin at override_hlc). OPS.md#wordstatus_set\",\"properties\":{\"entry_seq\":{\"\$ref\":\"../common.schema.json#/\$defs/entry_seq\",\"description\":\"Entry. entity_id is its decimal text.\"},\"origin\":{\"default\":\"manual\",\"description\":\"Who set it. Default 'manual'. 'jpdb_import' is only used by the server's import job.\",\"enum\":[\"manual\",\"jpdb_import\"]},\"status\":{\"description\":\"The override.\",\"enum\":[\"known\",\"never_forget\",\"blacklisted\",\"ignored\"]}},\"required\":[\"entry_seq\",\"status\"],\"title\":\"word.status_set\",\"type\":\"object\"}",
